/// <summary>
/// The <c>METSalesOrderLoadPlanningAidController</c> class is the helper class for the associated SRS Report.
/// </summary>
class METTransferOrderLoadPlanningController extends SrsReportRunController
{    
}

Method.Source:
public static METTransferOrderLoadPlanningController construct()
{
    return new METTransferOrderLoadPlanningController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METTransferOrderLoadPlanningController controller = METTransferOrderLoadPlanningController::construct();

    controller.parmReportName(ssrsReportStr(METTransferOrderLoadPlanningReport, Report));
    controller.parmArgs(_args);
    controller.parmShowDialog(false);

    METTransferOrderLoadPlanningContract transferOrderLoadPlanningContract = controller.parmReportContract().parmRdpContract() as METTransferOrderLoadPlanningContract;
    MetTransferOrderExtractScreenParameters metTransferOrderExtractScreenParameters = _args.parmObject();

    if (metTransferOrderExtractScreenParameters && transferOrderLoadPlanningContract)
    {
        str selectedExtratedOrders = _args.parm();
        if (strLen(selectedExtratedOrders) > 0)
        {
            transferOrderLoadPlanningContract.parmSelectedRecords(selectedExtratedOrders);
        }
        else
        {
            transferOrderLoadPlanningContract.parmSelectedRecords('');
        }
        transferOrderLoadPlanningContract.parmRouteID(metTransferOrderExtractScreenParameters.parmRoute());
        transferOrderLoadPlanningContract.parmConfirmedShipDateFrom(metTransferOrderExtractScreenParameters.parmShippingDateConfirmFrom());
        transferOrderLoadPlanningContract.parmConfirmedShipDateTo(metTransferOrderExtractScreenParameters.parmShippingDateConfirmTo());
        transferOrderLoadPlanningContract.parmFromWarehouse(metTransferOrderExtractScreenParameters.parmFromWarehouse());
        transferOrderLoadPlanningContract.parmToWarehouse(metTransferOrderExtractScreenParameters.parmToWarehouse());
        transferOrderLoadPlanningContract.parmRouteID(metTransferOrderExtractScreenParameters.parmRoute());
        transferOrderLoadPlanningContract.parmExtractStatus(metTransferOrderExtractScreenParameters.parmExtracted());
        transferOrderLoadPlanningContract.parmOrderSplitGroup(metTransferOrderExtractScreenParameters.parmOrderSplitGroup());
    }

    controller.startOperation();
}
